const root=document.getElementById("settings");const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const val=id=>saved[id]!==undefined?saved[id]:defaults[id];
function build(){root.innerHTML='';Object.entries(fieldData).forEach(([cat,ids])=>{if(!ids.length)return;const c=document.createElement('section');c.className='card';c.innerHTML='<h2>'+esc(cat)+'</h2>';ids.forEach(id=>{const f=fieldMap[id],v=val(id),r=document.createElement('div');r.className='row';r.innerHTML='<div><div class="name">'+esc(labels[id]||id)+'</div><div class="desc">'+f.min+' → '+f.max+' · bước '+f.step+'</div></div><div class="control"><input class="range" data-id="'+id+'" type="range" min="'+f.min+'" max="'+f.max+'" step="'+f.step+'" value="'+v+'"><input class="num" data-id="'+id+'" type="number" min="'+f.min+'" max="'+f.max+'" step="'+f.step+'" value="'+v+'"></div>';c.appendChild(r)});root.appendChild(c)});const t=document.createElement('section');t.className='card';t.innerHTML='<h2>Chế độ & công tắc</h2>';checkData.forEach(([id,d])=>{const v=saved[id]!==undefined?saved[id]:d,l=document.createElement('label');l.className='checkrow';l.innerHTML='<input type="checkbox" data-check="'+id+'" '+(v?'checked':'')+'><span>'+esc(checkLabels[id])+'</span>';t.appendChild(l)});root.appendChild(t);const s=document.createElement('section');s.className='card';s.innerHTML='<h2>Lựa chọn hệ thống</h2>';selectData.forEach(([id,opts])=>{const w=document.createElement('div');w.className='row';w.innerHTML='<div class="name">'+esc(id)+'</div><select class="select" data-select="'+id+'">'+opts.map(o=>'<option value="'+esc(o[0])+'">'+esc(o[1])+'</option>').join('')+'</select>';w.querySelector('select').value=saved[id]!==undefined?saved[id]:opts[0][0];s.appendChild(w)});root.appendChild(s);bind()}
function bind(){root.querySelectorAll('.range').forEach(r=>r.oninput=()=>{const n=root.querySelector('.num[data-id="'+r.dataset.id+'"]');n.value=r.value});root.querySelectorAll('.num').forEach(n=>n.oninput=()=>{const r=root.querySelector('.range[data-id="'+n.dataset.id+'"]');if(n.value!=='')r.value=Math.max(+r.min,Math.min(+r.max,+n.value))})}
function collect(){const o={};root.querySelectorAll('.range').forEach(r=>o[r.dataset.id]=r.value);root.querySelectorAll('[data-check]').forEach(c=>o[c.dataset.check]=c.checked);root.querySelectorAll('[data-select]').forEach(s=>o[s.dataset.select]=s.value);return o}
function toast(m){const t=document.getElementById('toast');t.textContent=m;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),1600)}
document.getElementById('apply').onclick=()=>{localStorage.setItem('atcx_settings',JSON.stringify(collect()));toast('Đã lưu Settings')};document.getElementById('back').onclick=()=>location.href='index.html';document.getElementById('reset').onclick=()=>{if(confirm('Khôi phục toàn bộ giá trị mặc định?')){localStorage.removeItem('atcx_settings');location.reload()}};build();

(function(){
"use strict";

const $=id=>document.getElementById(id);
const btn=$("quickUI");
const panel=$("quickUIPanel");
const close=$("quickUIClose");
const qLang=$("quickLang");
const qTheme=$("quickTheme");
const qBg=$("quickBg");
const qState=$("quickCookieState");

if(!btn||!panel)return;

function cookie(){
    return window.ATCXCookie||null;
}

function sync(){
    const c=cookie();
    const v=c?c.read():{};
    if(qLang)qLang.value=v.lang||"vi";
    if(qTheme)qTheme.value=v.theme||"dark";
    if(qBg)qBg.value=v.bg&&/^https?:/i.test(v.bg)?v.bg:"";
    if(qState)qState.textContent="Cookie: "+(c&&c.hasConsent()?"Đã chấp nhận":"Chưa chấp nhận");
}

function values(){
    return{
        lang:qLang?qLang.value:"vi",
        theme:qTheme?qTheme.value:"dark",
        bg:qBg?qBg.value.trim():""
    };
}

function preview(){
    const c=cookie();
    if(c)c.apply(values());
}

function save(){
    const c=cookie();
    if(!c){
        toast("Không tìm thấy hệ thống cookie");
        return;
    }
    if(!c.hasConsent()){
        c.ask();
        toast("Hãy chấp nhận cookie trước khi lưu");
        return;
    }
    const v=values();
    c.save(v);
    c.apply(v);
    if(qState)qState.textContent="Cookie: Đã chấp nhận";
    toast("Đã lưu giao diện");
}

function open(){
    sync();
    panel.classList.add("open");
    panel.setAttribute("aria-hidden","false");
}

function hide(){
    panel.classList.remove("open");
    panel.setAttribute("aria-hidden","true");
}

btn.addEventListener("click",open);
if(close)close.addEventListener("click",hide);
document.addEventListener("keydown",e=>{
    if(e.key==="Escape")hide();
});

if(qLang)qLang.addEventListener("change",preview);
if(qTheme)qTheme.addEventListener("change",preview);
if(qBg)qBg.addEventListener("input",preview);

document.querySelectorAll("[data-quick-bg]").forEach(b=>{
    b.addEventListener("click",()=>{
        if(qBg)qBg.value=b.dataset.quickBg||"";
        preview();
    });
});

const quickPreview=$("quickPreview");
const quickSave=$("quickSave");
const quickDelete=$("quickCookieDelete");

if(quickPreview)quickPreview.addEventListener("click",()=>{
    preview();
    toast("Đã áp dụng xem trước");
});

if(quickSave)quickSave.addEventListener("click",save);

if(quickDelete)quickDelete.addEventListener("click",()=>{
    const c=cookie();
    if(!c)return;
    c.delete();
    c.setConsent(false);
    sync();
    toast("Đã xóa dữ liệu cookie");
});

sync();
})();
